const styles = {
  root: {
    minHeight: '100vh',
    background: '#09090b', // 更深邃的深蓝黑
    color: '#fafafa',
    fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, sans-serif",
    display: 'flex',
    flexDirection: 'column',
  },
  header: {
    borderBottom: '1px solid #27272a',
    padding: '12px 24px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    background: 'rgba(9, 9, 11, 0.8)',
    backdropFilter: 'blur(12px)',
    position: 'sticky',
    top: 0,
    zIndex: 10,
  },
  headerLeft: { display: 'flex', alignItems: 'center', gap: '12px' },
  logo: {
    width: '30px', height: '30px',
    background: 'linear-gradient(135deg, #60a5fa 0%, #818cf8 100%)',
    borderRadius: '8px',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '14px',
    boxShadow: '0 0 15px rgba(96, 165, 250, 0.3)',
  },
  headerTitle: { fontSize: '14px', fontWeight: '600', color: '#ffffff', letterSpacing: '-0.02em' },
  headerSub: { fontSize: '11px', color: '#a1a1aa', marginTop: '1px' },
  sessionBadge: {
    fontSize: '10px', color: '#94a3b8',
    background: '#18181b',
    border: '1px solid #27272a',
    borderRadius: '6px', padding: '4px 8px',
    fontFamily: "'JetBrains Mono', 'IBM Plex Mono', monospace",
  },
  main: { flex: 1, display: 'flex', maxWidth: '760px', width: '100%', margin: '0 auto', flexDirection: 'column', padding: '0 20px' },
  messageList: { flex: 1, padding: '32px 0', display: 'flex', flexDirection: 'column', gap: '28px', overflowY: 'auto' },
  empty: {
    flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
    gap: '20px', color: '#71717a', padding: '60px 0',
  },
  emptyIcon: { fontSize: '32px', opacity: 0.8, color: '#3f3f46' },
  emptyTitle: { fontSize: '18px', color: '#e4e4e7', fontWeight: '500', letterSpacing: '-0.02em' },
  emptyHints: { display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center', marginTop: '4px', maxWidth: '500px' },
  hint: {
    fontSize: '13px', color: '#a1a1aa', background: '#18181b',
    border: '1px solid #27272a', borderRadius: '12px',
    padding: '8px 16px', cursor: 'pointer', transition: 'all 0.2s ease',
    hover: { background: '#27272a', color: '#ffffff' } // 逻辑中需对应处理 hover 或直接用 css
  },
  msgRow: (role) => ({
    display: 'flex',
    flexDirection: 'row', // 统一左对齐更符合研究型产品的阅读习惯，或者保留你的 row-reverse
    gap: '14px', alignItems: 'flex-start',
  }),
  avatar: (role) => ({
    width: '30px', height: '30px', borderRadius: '8px', flexShrink: 0,
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '10px', fontWeight: 'bold',
    background: role === 'user' ? '#27272a' : 'linear-gradient(135deg, #3b82f6, #6366f1)',
    color: role === 'user' ? '#a1a1aa' : '#fff',
    border: '1px solid rgba(255,255,255,0.05)',
  }),
  bubble: (role) => ({
    maxWidth: '85%',
    background: role === 'user' ? 'transparent' : '#18181b',
    border: role === 'user' ? 'none' : '1px solid #27272a',
    borderRadius: '12px',
    padding: role === 'user' ? '4px 0' : '16px',
  }),
  bubbleText: { fontSize: '15px', lineHeight: '1.6', color: role => role === 'user' ? '#ffffff' : '#d4d4d8', whiteSpace: 'pre-wrap' },
  stepsList: { marginTop: '12px', display: 'flex', flexWrap: 'wrap', gap: '8px' },
  step: {
    fontSize: '11px', fontFamily: "'JetBrains Mono', monospace",
    color: '#818cf8', background: 'rgba(129, 140, 248, 0.1)',
    border: '1px solid rgba(129, 140, 248, 0.2)',
    borderRadius: '6px', padding: '3px 8px',
  },
  sourcesList: { 
    marginTop: '16px', paddingTop: '12px', borderTop: '1px solid #27272a' 
  },
  sourceLabel: { fontSize: '10px', color: '#71717a', marginBottom: '8px', textTransform: 'uppercase', fontWeight: '600', letterSpacing: '0.05em' },
  sourceLink: {
    display: 'inline-flex', alignItems: 'center', fontSize: '12px', color: '#60a5fa',
    fontFamily: "'Inter', sans-serif",
    textDecoration: 'none', margin: '4px 8px 4px 0',
    background: 'rgba(59, 130, 246, 0.05)', padding: '4px 10px', borderRadius: '6px',
    border: '1px solid rgba(59, 130, 246, 0.1)',
  },
  thinking: {
    fontSize: '13px', color: '#71717a', fontStyle: 'normal',
    display: 'flex', alignItems: 'center', gap: '10px',
  },
  dot: (i) => ({
    width: '4px', height: '4px', borderRadius: '50%',
    background: '#6366f1', display: 'inline-block',
    animation: `pulse 1.2s ease-in-out ${i * 0.2}s infinite`,
  }),
  inputArea: {
    padding: '20px 0 32px',
    background: 'linear-gradient(to top, #09090b 80%, transparent)',
  },
  inputRow: {
    display: 'flex', gap: '10px', alignItems: 'flex-end',
    background: '#18181b', border: '1px solid #27272a',
    borderRadius: '16px', padding: '12px 14px',
    boxShadow: '0 4px 20px rgba(0,0,0,0.2)',
    transition: 'all 0.2s ease',
    focusWithin: { borderColor: '#3f3f46' }
  },
  textarea: {
    flex: 1, background: 'transparent', border: 'none', outline: 'none',
    color: '#ffffff', fontSize: '15px', lineHeight: '1.5',
    resize: 'none', fontFamily: "inherit",
    maxHeight: '150px', minHeight: '24px',
    caretColor: '#60a5fa',
  },
  sendBtn: (disabled) => ({
    width: '32px', height: '32px', borderRadius: '10px', border: 'none',
    background: disabled ? '#27272a' : '#ffffff',
    color: disabled ? '#52525b' : '#09090b',
    cursor: disabled ? 'not-allowed' : 'pointer',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '18px', flexShrink: 0, transition: 'all 0.2s ease',
  }),
  clearBtn: {
    fontSize: '11px', color: '#52525b', background: 'transparent',
    border: 'none', borderRadius: '6px',
    padding: '8px 0', cursor: 'pointer', marginTop: '4px',
    textDecoration: 'underline', textUnderlineOffset: '4px',
    transition: 'color 0.2s',
  },
};
